parameters.parameter:
var data = JSON.parse(value);

for (var i = 0; i < data.length; i++) {
    var alias = data[i]["{#IFALIAS}"] || "";
    alias = alias.replace(/^\s+|\s+$/g, '');

    data[i]["{#ROLE}"] = "";

    var m = alias.match(/^(FEX|UPL|OSPF|VPC|PTP|WAN|TRUNK)[ -]?(.*)$/);
    if (m) {
        data[i]["{#ROLE}"] = m[1];
        // data[i]["{#IFALIAS}"] = m[2].replace(/^\s+|\s+$/g, '');
    }
}

return JSON.stringify(data);
